import pandas as pd, numpy as np
from statsmodels.tsa.filters.hp_filter import hpfilter

def extract(path):
    df = pd.read_excel(path, header=None)
    annual = {}
    qvals=[]
    for _, row in df.iterrows():
        v=row[0]
        if isinstance(v, str):
            s=v.strip()
            if s.endswith('.') and s[:4].isdigit() and len(s[:4])==4:
                year=int(s[:4])
                if 1973 <= year <= 2023:
                    annual[year]=float(row[1])
            if s.startswith('2024:') or (qvals and (s.startswith('II.') or s.startswith('III'))):
                try:
                    qvals.append(float(row[1]))
                except:
                    pass
    annual[2024]=sum(qvals)/len(qvals)
    return pd.Series(annual).sort_index().astype(float)

pce=extract('/root/ERP-2025-table10.xls')
pfi=extract('/root/ERP-2025-table12.xls')
cpi=pd.read_excel('/root/CPI.xlsx', header=None).set_index(0).iloc[:,0].astype(float)
idx=range(1973,2025)
pce=pce.loc[idx]
pfi=pfi.loc[idx]
cpi=cpi.loc[idx]
real_pce=(pce/cpi).astype(float)
real_pfi=(pfi/cpi).astype(float)
cycle_pce,_=hpfilter(np.log(real_pce.values), lamb=100)
cycle_pfi,_=hpfilter(np.log(real_pfi.values), lamb=100)
cor=np.corrcoef(cycle_pce, cycle_pfi)[0,1]
print(cor)
